SELECT s1."c0" AS "p" FROM (SELECT s2."c7" AS "c0" FROM (SELECT s3."c0" AS "c0", s3."c1" AS "c1", s3."c2" AS "c2", s3."c3" AS "c3", s3."c4" AS "c4", s3."c5" AS "c5", s3."c6" AS "c6", (POWER(CAST(CAST(s3."c3" AS NUMBER(38,0)) AS FLOAT), CAST('2.0' AS FLOAT)) + CAST('0.0' AS FLOAT)) AS "c7" FROM (SELECT "d" AS "c0", "d2" AS "c1", "ts" AS "c2", "x" AS "c3", "s" AS "c4", "ok" AS "c5", ("v" + CAST('0.0' AS FLOAT)) AS "c6" FROM "events") AS s3) AS s2) AS s1
